<?php // phpcs:ignore WordPress.Files.FileName.InvalidClassFileName -- Matches the plugin's CamelCase-to-hyphen autoloader.
/**
 * Retains bounded, block-scoped styles generated by the design controls.
 *
 * @package Optin
 */

// phpcs:disable WordPress.NamingConventions.ValidVariableName.UsedPropertyNotSnakeCase -- Preserve the shared Gutenberg campaign JSON field names.

namespace OPTN\Includes\Utils;

defined( 'ABSPATH' ) || exit;

/** Removes obsolete custom code and validates the generated stylesheet cache. */
class CampaignStyles {

	private const LEGACY_PLACEHOLDER      = '{{optn}}';
	private const LEGACY_PLACEHOLDER_MARK = "\0p";
	private const LEGACY_NULL_MARK        = "\0n";
	private const LEGACY_SUFFIX_LENGTH    = 16;
	private const LEGACY_MATCH_BYTES      = 4 * 1024 * 1024;

	/**
	 * Remove legacy code fields and constrain the remaining generated styles.
	 *
	 * @param \stdClass $data Validated campaign envelope, modified in place.
	 * @return void
	 */
	public static function sanitize( $data ) {
		$ids     = array();
		$legacy  = array();
		$has_css = isset( $data->css ) && '' !== $data->css;
		$blocks  = function ( $items ) use ( &$blocks, &$ids ) {
			foreach ( $items as $item ) {
				$block = $item[1];
				if ( preg_match( '/^[a-zA-Z0-9_-]+$/D', $block->clientId ) ) {
					$ids[ $block->clientId ] = true;
				}
				if ( isset( $block->innerBlocks->value ) ) {
					$blocks( $block->innerBlocks->value );
				}
			}
		};
		foreach ( $data->steps as $step ) {
			$blocks( $step->blocks->value );
		}
		$walk = function ( &$value, $owner = '' ) use ( &$walk, &$ids, &$legacy, $has_css ) {
			if ( ! is_array( $value ) && ! is_object( $value ) ) {
				return;
			}
			if ( is_object( $value ) && is_string( $value->clientId ?? null ) && isset( $ids[ $value->clientId ] ) ) {
				$owner = $value->clientId;
			}
			foreach ( $value as $key => &$item ) {
				if ( 'customCss' === $key ) {
					if ( $has_css && is_string( $item ) && '' !== trim( $item ) ) {
						$legacy[] = array( $owner, $item );
					}
					if ( is_object( $value ) ) {
						unset( $value->$key );
					} else {
						unset( $value[ $key ] );
					}
				} else {
					$walk( $item, $owner );
				}
			}
			unset( $item );
		};
		$walk( $data );
		if ( ! $has_css ) {
			return;
		}

		$literal   = array();
		$templates = array();
		foreach ( $legacy as list( $owner, $custom_css ) ) {
			// Mark placeholders before parsing, just as the old builder substituted them before minifying.
			$custom_css = strtr(
				$custom_css,
				array(
					self::LEGACY_PLACEHOLDER => self::LEGACY_PLACEHOLDER_MARK,
					"\0"                     => self::LEGACY_NULL_MARK,
				)
			);
			self::rules(
				$custom_css,
				static function ( $selector, $body ) use ( $owner, &$literal, &$templates ) {
					$rule = $selector . '{' . $body . '}';
					// The cached stylesheet has already had literal null bytes stripped.
					if ( false !== strpos( $rule, self::LEGACY_NULL_MARK ) ) {
						return '';
					}
					$key  = preg_replace( '/\s+/', '', $rule );
					$last = strrpos( $key, self::LEGACY_PLACEHOLDER_MARK );
					if ( false === $last ) {
						$literal[ $key ] = true;
					} else {
						// The literal suffix survives substitution and narrows the candidates for each cached rule.
						$length = min( self::LEGACY_SUFFIX_LENGTH, strlen( $key ) - $last - strlen( self::LEGACY_PLACEHOLDER_MARK ) );
						$templates[ $length ][ substr( $key, -$length ) ][ $key ][ $owner ] = true;
					}
					return '';
				}
			);
		}

		$remaining = self::LEGACY_MATCH_BYTES;
		// Read-time sanitization also removes custom rules cached before this feature was removed.
		$data->css = self::rules(
			$data->css,
			static function ( $selector, $body ) use ( $ids, $literal, $templates, &$remaining ) {
				if ( ! self::is_block_selector( $selector, $ids ) || strpbrk( $body, '{}<>\\' ) !== false ) {
					return '';
				}
				if ( $literal || $templates ) {
					$key = preg_replace( '/\s+/', '', $selector . '{' . $body . '}' );
					if ( isset( $literal[ $key ] ) || self::matches_legacy_template( $key, $templates, $ids, $remaining ) ) {
						return '';
					}
				}
				$declarations = self::declarations( $body );
				return '' === $declarations ? '' : $selector . '{' . $declarations . '}';
			}
		);
	}

	/**
	 * Match a cached rule by inferring the replacement from its length and contents.
	 *
	 * @param string $key       Cached rule fingerprint.
	 * @param array  $templates Legacy template fingerprints indexed by their literal suffixes.
	 * @param array  $ids       Campaign block IDs.
	 * @param int    $remaining Remaining comparison bytes for this campaign.
	 * @return bool Whether to discard the cached rule as legacy CSS.
	 */
	private static function matches_legacy_template( $key, $templates, $ids, &$remaining ) {
		$key_length = strlen( $key );
		foreach ( $templates as $suffix_length => $group ) {
			foreach ( $group[ substr( $key, -$suffix_length ) ] ?? array() as $template => $owners ) {
				$template_length = strlen( $template );
				$cost            = $key_length + $template_length;
				if ( $cost > $remaining ) {
					// Omit rules with unresolved legacy candidates once the shared work budget runs out.
					$remaining = 0;
					return true;
				}
				$remaining -= $cost;

				// Each placeholder expands to the same selector, so the length difference identifies its size.
				$count      = substr_count( $template, self::LEGACY_PLACEHOLDER_MARK );
				$difference = $key_length - $template_length;
				if ( $difference < 0 || 0 !== $difference % $count ) {
					continue;
				}

				$offset      = strpos( $template, self::LEGACY_PLACEHOLDER_MARK );
				$replacement = substr( $key, $offset, strlen( self::LEGACY_PLACEHOLDER_MARK ) + intdiv( $difference, $count ) );
				if ( preg_match( '/^(?:#|\.optn-)([a-zA-Z0-9_-]+)$/D', $replacement, $match )
					&& isset( $ids[ $match[1] ] )
					&& ( isset( $owners[''] ) || isset( $owners[ $match[1] ] ) )
					&& str_replace( self::LEGACY_PLACEHOLDER_MARK, $replacement, $template ) === $key
				) {
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Accept only flat block rules and the two responsive wrappers emitted by the builder.
	 *
	 * Unknown at-rules, unscoped selectors, malformed nesting and sibling escapes are discarded.
	 * This deliberately accepts a smaller grammar than arbitrary CSS.
	 *
	 * @param string   $css    Stylesheet to parse.
	 * @param callable $rule   Receives a selector and declaration body and returns the CSS to keep.
	 * @param int      $depth  Current wrapper depth.
	 * @return string Safe generated stylesheet.
	 */
	private static function rules( $css, $rule, $depth = 0 ) {
		if ( $depth > 2 ) {
			return '';
		}
		$css    = preg_replace( '#/\*.*?\*/#s', '', $css );
		$length = strlen( $css );
		$output = '';
		$start  = 0;
		$open   = null;
		$level  = 0;
		$quote  = '';
		for ( $i = 0; $i < $length; ++$i ) {
			$char = $css[ $i ];
			if ( '' !== $quote ) {
				if ( '\\' === $char ) {
					++$i;
				} elseif ( $char === $quote ) {
					$quote = '';
				}
				continue;
			}
			if ( '"' === $char || "'" === $char ) {
				$quote = $char;
			} elseif ( ';' === $char && 0 === $level ) {
				// Discard statement at-rules such as imports, never append them to a following selector.
				$start = $i + 1;
			} elseif ( '{' === $char ) {
				if ( 0 === $level ) {
					$open = $i;
				}
				++$level;
			} elseif ( '}' === $char ) {
				if ( 0 === $level ) {
					return '';
				}
				--$level;
				if ( 0 !== $level ) {
					continue;
				}
				// Preserve the null byte used to mark legacy placeholders.
				$selector = trim( substr( $css, $start, $open - $start ), " \t\n\r\v" );
				$body     = substr( $css, $open + 1, $i - $open - 1 );
				$start    = $i + 1;
				if ( preg_match( '/^@media only screen and \(max-width:\s*767px\)$/D', $selector ) || preg_match( '/^@media only screen and \(min-width:\s*768px\) and \(max-width:\s*(?:1023|1139)px\)$/D', $selector ) ) {
					$inner = self::rules( $body, $rule, $depth + 1 );
					if ( '' !== $inner ) {
						$output .= $selector . '{' . $inner . '}';
					}
					continue;
				}
				$output .= $rule( $selector, $body );
			}
		}
		return 0 === $level && '' === $quote && '' === trim( substr( $css, $start ) ) ? $output : '';
	}

	/**
	 * Require every selector arm to start at a known block, with no sibling combinators.
	 *
	 * @param string $selector Rule selector, including generated pseudo-classes and attributes.
	 * @param array  $ids      Campaign block IDs.
	 * @return bool Whether each selector remains scoped to a campaign block.
	 */
	private static function is_block_selector( $selector, $ids ) {
		if ( '' === $selector || preg_match( '/[\\\\@{};<>+~]|\b(?:html|body)\b|:root\b/i', $selector ) ) {
			return false;
		}
		// Commas in :is(), :has(), :not(), or quoted attributes do not start another selector arm.
		$arms  = array();
		$start = 0;
		$depth = 0;
		$quote = '';
		for ( $i = 0, $length = strlen( $selector ); $i < $length; ++$i ) {
			$char = $selector[ $i ];
			if ( '' !== $quote ) {
				if ( $char === $quote ) {
					$quote = '';
				}
			} elseif ( '"' === $char || "'" === $char ) {
				$quote = $char;
			} elseif ( '(' === $char || '[' === $char ) {
				++$depth;
			} elseif ( ')' === $char || ']' === $char ) {
				if ( --$depth < 0 ) {
					return false;
				}
			} elseif ( ',' === $char && 0 === $depth ) {
				$arms[] = substr( $selector, $start, $i - $start );
				$start  = $i + 1;
			}
		}
		$arms[] = substr( $selector, $start );
		foreach ( $arms as $arm ) {
			if ( ! preg_match( '/^(?:#|\.optn-)([a-zA-Z0-9_-]+)(?=[\s.#:\[*]|$)/D', trim( $arm ), $match ) || ! isset( $ids[ $match[1] ] ) ) {
				return false;
			}
		}
		return 0 === $depth && '' === $quote;
	}

	/**
	 * Use WordPress's property, function and URL checks for generated declarations.
	 *
	 * @param string $body CSS declarations from a scoped rule.
	 * @return string Safe declarations.
	 */
	private static function declarations( $body ) {
		$properties = static function ( $styles ) {
			return array_merge(
				$styles,
				array(
					'display',
					'position',
					'inset',
					'overflow',
					'overflow-wrap',
					'object-fit',
					'object-position',
					'transform',
					'transform-origin',
					'translate',
					'transition',
					'transition-duration',
					'transition-property',
					'transition-timing-function',
					'filter',
					'-webkit-filter',
					'clip-path',
					'mask',
					'mask-border',
					'mix-blend-mode',
					'content',
					'paint-order',
					'pointer-events',
					'cursor',
					'hyphens',
					'stroke-width',
					'stroke-dashoffset',
					'stroke-linejoin',
					'list-style-position',
					'border-image',
					'border-image-slice',
					'border-inline',
					'padding-inline',
					'rotate',
					'-webkit-mask',
					'-webkit-text-stroke-width',
					'-webkit-text-stroke-color',
					'background-clip',
					'background-repeat',
					'grid-column',
					'grid-row',
					'white-space',
					'text-shadow',
				)
			);
		};
		$functions  = static function ( $allowed, $test ) {
			// Extend core only for the builder's color, transform, image-frame and filter functions.
			// Repeated passes handle nested rgba() inside drop-shadow(), without permitting unknown functions or URLs.
			for ( $i = 0; $i < 4; ++$i ) {
				$test = preg_replace( '/\b(?:rgba?|hsla?|translate[XYZ]?|translate3d|rotate[XYZ]?|rotate3d|scale[XYZ]?|scale3d|skew[XY]?|matrix|matrix3d|perspective|blur|brightness|contrast|grayscale|hue-rotate|invert|opacity|saturate|sepia|cubic-bezier|drop-shadow|(?:repeating-)?(?:linear|radial|conic)-gradient|cos|sin|tan|polygon|circle|ellipse|inset|rect|xywh)\([-+a-zA-Z0-9_#.,%\s*\/]*\)/', '', $test );
			}
			return ! preg_match( '%[\\\\\(&=}]|/\*%', $test );
		};
		add_filter( 'safe_style_css', $properties );
		add_filter( 'safecss_filter_attr_allow_css', $functions, PHP_INT_MAX, 2 );
		try {
			return safecss_filter_attr( $body );
		} finally {
			remove_filter( 'safe_style_css', $properties );
			remove_filter( 'safecss_filter_attr_allow_css', $functions, PHP_INT_MAX );
		}
	}
}
